import { ExternalTokenizer } from '@lezer/lr';

// Character codes.
const eof = -1;
const dash = 45;
const space = 32;
const dot = 46;
const comma = 44;

function isNumber(charCode: number): boolean {
  // Numpad key codes are already handled by codemirror.
  return charCode >= 48 && charCode <= 57;
}

export const valueTokenizer = new ExternalTokenizer((inputStream) => {
  const currCharCode = inputStream.peek(0);

  // Character is not a number and not '-' -> definitely not a number.
  if (!isNumber(currCharCode) && currCharCode !== dash) {
    return;
  }

  // If the number starts with a '-', we need to consider that when comparing
  // the length of the matched string and the final peekPosition.
  const peekOffset = currCharCode === dash ? 1 : 0;

  // Array of digits and separators (.|,) so we can check if the potential
  // number actually is a number with the regex at the end.
  // We already checked the character at the current position, so we can already
  // add a digit here ('-' doesn't make a difference for the regex).
  const potentialNumberChars = ['d'];

  let peekPosition = 1;
  let peekCharCode = inputStream.peek(peekPosition);
  // As long as the character is either a digit, '.', or ',', we keep pushing
  // the characters to the array.
  while (
    isNumber(peekCharCode) ||
    peekCharCode === dot ||
    peekCharCode === comma
  ) {
    isNumber(peekCharCode)
      ? potentialNumberChars.push('d')
      : potentialNumberChars.push(peekCharCode === dot ? '.' : ',');
    peekPosition += 1;
    peekCharCode = inputStream.peek(peekPosition);
  }

  // Only if the character right after the potential number is either the end of
  // the input or a space, the token may be a number. If not, we just return.
  const charAfterPotentialNumber = inputStream.peek(peekPosition);
  if (
    peekPosition === 0 ||
    !(charAfterPotentialNumber === eof || charAfterPotentialNumber === space)
  ) {
    return;
  }

  // Crazy shit regex magic to check if the input is a valid number or not.
  // The regex matches everything with an arbitrary number of digits at the start (at least 1)
  // followed by optional thousands separators and groups of 3 digits and an optional decimal
  // separator with 1 to n decimals.
  // If the thousands separator is a '.', the decimal separator must be a ',' and vice versa.
  // The locale can only be checked at runtime, so we allow both for the tokenization.

  const potentialNumber = potentialNumberChars.join('');
  const numberMatch = (potentialNumber.match(
    /^-?(d+(?:(\.(?:d{3})+)+|d*)(,d+)?)$|(d+(?:(,(?:d{3})+)+|d*)(\.d+)?)$/,
  ) || [])[0];

  if (numberMatch?.length !== peekPosition + peekOffset) {
    return;
  }

  inputStream.acceptToken(1, peekPosition + peekOffset);
});
